<?php
namespace App\Application\Compliance;use App\Application\Audit\AuditWriter;use App\Application\Events\OutboxWriter;use App\Models\{RegulatoryReportDefinition,RegulatoryReportRun,User};use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;
final class RegulatoryReportingService{public function __construct(private AuditWriter$a,private OutboxWriter$o){}private function hash(array$d):string{ksort($d);return hash('sha256',json_encode($d,JSON_THROW_ON_ERROR));}public function define(array$d,User$u):RegulatoryReportDefinition{return RegulatoryReportDefinition::create([...$d,'status'=>'DRAFT','schema_hash'=>$this->hash($d['schema']),'created_by'=>$u->id]);}public function approveDefinition(RegulatoryReportDefinition$x,User$u):RegulatoryReportDefinition{if($x->status!=='DRAFT'||$x->created_by===$u->id)throw ValidationException::withMessages(['status'=>__('wave9.maker_checker')]);$overlap=RegulatoryReportDefinition::where('code',$x->code)->where('status','ACTIVE')->where('effective_from','<=',$x->effective_until??'9999-12-31')->where(fn($q)=>$q->whereNull('effective_until')->orWhere('effective_until','>=',$x->effective_from))->exists();if($overlap)throw ValidationException::withMessages(['effective_from'=>__('wave9.rule_overlap')]);$x->update(['status'=>'ACTIVE','approved_by'=>$u->id,'approved_at'=>now()]);return$x->refresh();}public function prepare(string$tenant,RegulatoryReportDefinition$d,array$in,User$u):RegulatoryReportRun{$hash=$this->hash($in['payload']);if($x=RegulatoryReportRun::where(['tenant_id'=>$tenant,'idempotency_key'=>$in['idempotency_key']])->first()){if(!hash_equals($x->payload_hash,$hash))throw ValidationException::withMessages(['idempotency_key'=>__('wave9.idempotency_conflict')]);return$x;}if($d->status!=='ACTIVE')throw ValidationException::withMessages(['definition'=>__('wave9.definition_inactive')]);return RegulatoryReportRun::create([...$in,'tenant_id'=>$tenant,'definition_id'=>$d->id,'status'=>'DRAFT','payload_hash'=>$hash,'prepared_by'=>$u->id]);}public function approve(RegulatoryReportRun$x,User$u):RegulatoryReportRun{if($x->status!=='DRAFT'||$x->prepared_by===$u->id)throw ValidationException::withMessages(['status'=>__('wave9.maker_checker')]);$x->update(['status'=>'APPROVED','approved_by'=>$u->id,'approved_at'=>now()]);$this->o->record('regulatory.report.approved','regulatory_report_run',$x->id,['run_id'=>$x->id]);return$x->refresh();}public function submit(RegulatoryReportRun$x):RegulatoryReportRun{if(!in_array($x->status,['APPROVED','RETRY_PENDING'],true))throw ValidationException::withMessages(['status'=>__('wave9.transition_invalid')]);$x->update(['status'=>'SUBMITTING','attempt_count'=>$x->attempt_count+1,'next_attempt_at'=>null,'submitted_at'=>now()]);$this->o->record('regulatory.report.submitted','regulatory_report_run',$x->id,['run_id'=>$x->id,'attempt'=>$x->attempt_count]);return$x->refresh();}public function fail(RegulatoryReportRun$x,string$r):RegulatoryReportRun{$x->update(['status'=>'RETRY_PENDING','failure_reason'=>$r,'next_attempt_at'=>now()->addMinutes(15)]);return$x->refresh();}public function acknowledge(RegulatoryReportRun$x,string$r):RegulatoryReportRun{/* REQ-RPT-001: only a run the regulator received (SUBMITTING) can be acknowledged. */if($x->status!=='SUBMITTING')throw ValidationException::withMessages(['status'=>__('wave9.transition_invalid')]);$x->update(['status'=>'ACKNOWLEDGED','external_reference'=>$r,'submitted_at'=>$x->submitted_at??now(),'acknowledged_at'=>now(),'failure_reason'=>null]);$this->o->record('regulatory.report.acknowledged','regulatory_report_run',$x->id,['run_id'=>$x->id,'external_reference'=>$r]);return$x->refresh();}public function reverse(RegulatoryReportRun$x,string$r,User$u):RegulatoryReportRun{if($x->status!=='ACKNOWLEDGED'||$x->approved_by===$u->id)throw ValidationException::withMessages(['status'=>__('wave9.maker_checker')]);$x->update(['status'=>'REVERSED','reversed_at'=>now(),'failure_reason'=>$r]);$this->a->record('regulatory.report.reversed','regulatory_report_run',$x->id,['reason'=>$r]);return$x->refresh();}}
